create extension if not exists pgcrypto;
do $$ begin create type public.user_role as enum ('passenger','driver','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type public.ride_status as enum ('requested','offering','driver_selected','driver_arriving','in_progress','completed','cancelled'); exception when duplicate_object then null; end $$;
do $$ begin create type public.offer_status as enum ('pending','accepted','rejected','countered','expired'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role public.user_role not null default 'passenger',created_at timestamptz default now());
create table if not exists public.driver_profiles(user_id uuid primary key references profiles(id) on delete cascade,area text,village text,approved boolean not null default false,online boolean not null default false,vehicle_plate text,rating numeric(3,2) default 5,created_at timestamptz default now());
create table if not exists public.service_areas(id uuid primary key default gen_random_uuid(),name text unique not null,enabled boolean default true);
create table if not exists public.villages(id uuid primary key default gen_random_uuid(),area_id uuid references service_areas(id),name text not null,enabled boolean default true,unique(area_id,name));
create table if not exists public.fare_rules(id uuid primary key default gen_random_uuid(),name text unique not null default 'default',base_fare numeric(10,2) default 10,price_per_km numeric(10,2) default 5,minimum_fare numeric(10,2) default 30,negotiation_pct numeric(5,2) default 20,waiting_per_minute numeric(10,2) default 1,extra_fee numeric(10,2) default 0,enabled boolean default true);
create table if not exists public.rides(id uuid primary key default gen_random_uuid(),passenger_id uuid not null references profiles(id),driver_id uuid references profiles(id),pickup_lat double precision not null,pickup_lng double precision not null,destination_lat double precision not null,destination_lng double precision not null,pickup_label text,destination_label text,route_distance_km numeric(8,2),eta_minutes int,suggested_fare numeric(10,2),passenger_initial_offer numeric(10,2),final_fare numeric(10,2),status ride_status not null default 'requested',created_at timestamptz default now(),fare_locked_at timestamptz);
create table if not exists public.ride_offers(id uuid primary key default gen_random_uuid(),ride_id uuid not null references rides(id) on delete cascade,sender_id uuid not null references profiles(id),sender_role user_role not null,amount numeric(10,2) not null,status offer_status not null default 'pending',counter_of uuid references ride_offers(id),created_at timestamptz default now(),expires_at timestamptz default now()+interval '90 seconds');
create table if not exists public.driver_locations(user_id uuid primary key references profiles(id) on delete cascade,lat double precision not null,lng double precision not null,updated_at timestamptz default now());
create table if not exists public.complaints(id uuid primary key default gen_random_uuid(),ride_id uuid references rides(id),opened_by uuid references profiles(id),category text,body text not null,status text default 'open',created_at timestamptz default now());
create table if not exists public.ratings(id uuid primary key default gen_random_uuid(),ride_id uuid unique references rides(id),passenger_id uuid references profiles(id),driver_id uuid references profiles(id),passenger_rating int check(passenger_rating between 1 and 5),driver_rating int check(driver_rating between 1 and 5),comment text,created_at timestamptz default now());
insert into service_areas(name) values('العسيرات'),('جرجا'),('برديس'),('البلينا') on conflict(name) do nothing;
insert into fare_rules(name) values('default') on conflict(name) do nothing;
alter table profiles enable row level security;alter table driver_profiles enable row level security;alter table rides enable row level security;alter table ride_offers enable row level security;alter table driver_locations enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role='admin')$$;
create policy "profile self/admin" on profiles for select using(id=auth.uid() or is_admin());
create policy "driver self/admin" on driver_profiles for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create policy "rides parties/admin" on rides for select using(passenger_id=auth.uid() or driver_id=auth.uid() or is_admin());
create policy "ride create" on rides for insert with check(passenger_id=auth.uid());
create policy "ride update parties/admin" on rides for update using(passenger_id=auth.uid() or driver_id=auth.uid() or is_admin());
create policy "offers parties/admin" on ride_offers for all using(sender_id=auth.uid() or exists(select 1 from rides r where r.id=ride_id and (r.passenger_id=auth.uid() or r.driver_id=auth.uid())) or is_admin()) with check(sender_id=auth.uid() or is_admin());
create policy "locations self/admin" on driver_locations for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create or replace function public.accept_offer(p_offer_id uuid) returns rides language plpgsql security definer set search_path=public as $$declare o ride_offers;r rides;begin select * into o from ride_offers where id=p_offer_id for update;select * into r from rides where id=o.ride_id for update;if o.id is null then raise exception 'offer_not_found';end if;if r.final_fare is not null then raise exception 'fare_already_locked';end if;if o.expires_at<now() then raise exception 'offer_expired';end if;if not(o.sender_id=auth.uid() or r.passenger_id=auth.uid() or r.driver_id=auth.uid()) then raise exception 'not_allowed';end if;update ride_offers set status='accepted' where id=o.id;update ride_offers set status='rejected' where ride_id=r.id and id<>o.id and status='pending';update rides set final_fare=o.amount,fare_locked_at=now(),status='driver_selected' where id=r.id;return (select * from rides where id=r.id);end;$$;
-- For pilot use Postgres Changes. At larger scale use Broadcast/private channels with authorization.
alter publication supabase_realtime add table rides;alter publication supabase_realtime add table ride_offers;alter publication supabase_realtime add table driver_locations;
